"""widened_check.py -- ml-logic: the group generated by engine letters plus the widened letter CS = diag(1,1,1,i)
at block 2 (CS is a monomial Z4 letter, so it is in the widened free group B').  The engine group has 46080 elements
(fbound.py); with CS the BFS passes any cap (Clifford + CS is a universal gate set, so the group is infinite and dense
in its closure), hence no block-uniform f-bound of Burnside-Brauer type exists in the widened game; only the per-word
bound of Theorem F applies.  Usage: python3 -I widened_check.py  (< 1 GB, < 1 min)"""
import sys
import os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np
import fbound as F
L = F.letters(2); L["CS"] = np.diag([1, 1, 1, 1j]).astype(complex)
gens = list(L.values()); I = np.eye(4, dtype=complex)
seen = {F.key(I)}; frontier = [I]; depth = 0; cap = 300000
while frontier and len(seen) <= cap:
    nxt = []
    for g in frontier:
        for s in gens:
            h = s @ g; k = F.key(h)
            if k not in seen: seen.add(k); nxt.append(h)
    frontier = nxt; depth += 1
    print(f"depth {depth}: {len(seen)} elements", flush=True)
print("cap passed" if len(seen) > cap else "closed", "; engine group alone: 46080")
